mapper.select:

WHERE 1 = 1

    AND CITD.ID = #{dto.id}


    AND CITD.`NAME` = #{dto.name}


    AND CITD.`GROUPING` = #{dto.grouping}


    AND CITD.ICON_TREE_TYPE = #{dto.iconTreeType}

SELECT CITD.id, CITD.rec_ver, CITD.header_id, CITD.header_id AS PARENT_ID, CITD.name, CITD.`grouping`, CITD.order_num, CITD.remark, CITD.icon_tree_type, CITD.ICON_ID, CITD.PARENT_ID FROM COMMON_ICON_TEMPLATE_DETAIL CITD WHERE 1 = 1
AND CITD.ID = #{dto.id}
AND CITD.`NAME` = #{dto.name}
AND CITD.`GROUPING` = #{dto.grouping}
AND CITD.ICON_TREE_TYPE = #{dto.iconTreeType}

SELECT MAX(ORDER_NUM)
FROM common_icon_template_detail citd
where 1 = 1
AND CITD.LOGIC_DEL = 0
AND CITD.HEADER_ID = #{dto.headerId}
AND CITD.ICON_TREE_TYPE = #{dto.iconTreeType}

    AND CITD.`GROUPING` = #{dto.grouping}


    AND CITD.PARENT_ID = #{dto.parentId}
